import io, sys
R = "D:\\Бекасыл КЖ КМ\\"
def rd(p): return io.open(p, encoding="utf-8").read()
def wr(p, s): io.open(p, "w", encoding="utf-8", newline="").write(s)
def ins_after(p, anchor, text):
    s = rd(p); nl = "\r\n" if "\r\n" in s else "\n"
    lines = s.split(nl); idx = [i for i, l in enumerate(lines) if anchor in l]
    if not idx: print("ANCHOR NOT FOUND", p, anchor); sys.exit(1)
    i = idx[-1]; lines[i+1:i+1] = text.split("\n"); wr(p, nl.join(lines)); print("ok", p.split("\\")[-1], i + 1)

